 100→export const action = async ({ request }: ActionFunctionArgs) => {
 101→  try {
 102→    const { session, admin } = await authenticate.admin(request);
 103→    const shop = session.shop;
 104→    const formData = await request.formData();
 105→    const intent = formData.get("intent");
 106→
 107→    if (intent === "save") {
 108→      const data = {
 109→        position: String(formData.get("position") || "inline"),
 110→        primaryColor: String(formData.get("primaryColor") || "#008060"),
 111→        successColor: String(formData.get("successColor") || "#008060"),
 112→        errorColor: String(formData.get("errorColor") || "#D72C0D"),
 113→        backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
 114→        textColor: String(formData.get("textColor") || "#202223"),
 115→        heading: String(formData.get("heading") || "Check Delivery Availability"),
 116→        placeholder: String(formData.get("placeholder") || "Enter your zip code"),
 117→        buttonText: String(formData.get("buttonText") || "Check"),
 118→        successMessage: String(
 119→          formData.get("successMessage") ||
 120→            "Great news! We deliver to your area.",
 121→        ),
 122→        errorMessage: String(
 123→          formData.get("errorMessage") ||
 124→            "Sorry, we don't deliver to this area yet.",
 125→        ),
 126→        notFoundMessage: String(
 127→          formData.get("notFoundMessage") ||
 128→            "We currently do not ship to this ZIP code.",
 129→        ),
 130→        showEta: formData.get("showEta") === "true",
 131→        showZone: formData.get("showZone") === "true",
 132→        showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
 133→        showCod: formData.get("showCod") === "true",
 134→        showReturnPolicy: formData.get("showReturnPolicy") === "true",
 135→        showCutoffTime: formData.get("showCutoffTime") === "true",
 136→        showDeliveryDays: formData.get("showDeliveryDays") === "true",
 137→        blockCartOnInvalid: formData.get("blockCartOnInvalid") === "true",
 138→        blockCheckoutInCart: formData.get("blockCheckoutInCart") === "true",
 139→        showSocialProof: formData.get("showSocialProof") === "true",
 140→        borderRadius: String(formData.get("borderRadius") || "8"),
 141→        customCss: String(formData.get("customCss") || "") || null,
 142→      };
 143→
 144→      // Server-side plan gating: strip premium fields the shop's plan doesn't allow
 145→      const subscription = await getShopSubscription(shop);
 146→      const limits = PLAN_LIMITS[subscription.planTier];
 147→      if (!limits.widgetFullCustom) {
 148→        data.primaryColor = "#008060";
 149→        data.successColor = "#008060";
 150→        data.errorColor = "#D72C0D";
 151→        data.backgroundColor = "#FFFFFF";
 152→        data.textColor = "#202223";
 153→        data.position = "inline";
 154→      }
 155→      if (!limits.showEtaCodReturn) {
 156→        data.showEta = false;
 157→        data.showZone = false;
 158→        data.showCod = false;
 159→        data.showReturnPolicy = false;
 160→        data.showCutoffTime = false;
 161→        data.showDeliveryDays = false;
 162→      }
 163→      if (!limits.customCss) {
 164→        data.customCss = null;
 165→      }
 166→      if (!limits.cartBlocking) {
 167→        data.blockCartOnInvalid = false;
 168→        data.blockCheckoutInCart = false;
 169→      }
 170→
 171→      await db.widgetConfig.upsert({
 172→        where: { shop },
 173→        create: { shop, ...data },
 174→        update: data,
 175→      });
 176→
 177→      await syncConfigMetafield(admin, data);
 178→
 179→      return { success: true };
 180→    }
 181→
 182→    if (intent === "reset") {
 183→      const resetData = {
 184→        position: "inline",
 185→        primaryColor: "#008060",
 186→        successColor: "#008060",
 187→        errorColor: "#D72C0D",
 188→        backgroundColor: "#FFFFFF",
 189→        textColor: "#202223",
 190→        heading: "Check Delivery Availability",
 191→        placeholder: "Enter your zip code",
 192→        buttonText: "Check",
 193→        successMessage: "Great news! We deliver to your area.",
 194→        errorMessage: "Sorry, we don't deliver to this area yet.",
 195→        notFoundMessage: "We currently do not ship to this ZIP code.",
 196→        showEta: true,
 197→        showZone: false,
 198→        showWaitlistOnFailure: false,
 199→        showCod: true,
 200→        showReturnPolicy: true,
 201→        showCutoffTime: true,
 202→        showDeliveryDays: true,
 203→        blockCartOnInvalid: false,
 204→        blockCheckoutInCart: false,
 205→        showSocialProof: true,
 206→        borderRadius: "8",
 207→        customCss: null,
 208→      };
 209→
 210→      await db.widgetConfig.upsert({
 211→        where: { shop },
 212→        create: { shop },
 213→        update: resetData,
 214→      });
 215→
 216→      await syncConfigMetafield(admin, resetData);
 217→
 218→      return { success: true, action: "reset" };
 219→    }
 220→
 221→    return null;
 222→  } catch {
 223→    return new Response(JSON.stringify({ error: "Failed to save widget settings." }), {
 224→      status: 500,
 225→      headers: { "Content-Type": "application/json" },
 226→    });
 227→  }
 228→};
