 354→  const p = cfg.primaryColor;
 355→  const s = cfg.successColor;
 356→  const e = cfg.errorColor;
 357→  const btnRadius = (cfg.borderRadius || "10") + "px";
 358→  const base =
 359→    "@keyframes zcc-slide-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}" +
