 952→  );
 953→  const [showCod, setShowCod] = useState(c.showCod ?? true);
 954→  const [showReturnPolicy, setShowReturnPolicy] = useState(c.showReturnPolicy ?? true);
 955→  const [showCutoffTime, setShowCutoffTime] = useState(c.showCutoffTime ?? true);
 956→  const [showDeliveryDays, setShowDeliveryDays] = useState(c.showDeliveryDays ?? true);
 957→  const [blockCartOnInvalid, setBlockCartOnInvalid] = useState(c.blockCartOnInvalid ?? false);
