 961→  const [customCss, setCustomCss] = useState(c.customCss || "");
 962→
 963→  // Unsaved changes tracking
 964→  const [isDirty, setIsDirty] = useState(false);
 965→
 966→  // Preview state
 967→  const [previewState, setPreviewState] = useState<
 968→    "idle" | "success" | "error" | "notfound"
 969→  >("idle");
