 976→
 977→  // Clear dirty flag after successful save
 978→  useEffect(() => {
 979→    if (
 980→      fetcher.state === "idle" &&
 981→      fetcher.data &&
 982→      "success" in fetcher.data &&
 983→      fetcher.data.success
